module top_tiny_soc (
	clk_i,
	rst_ni,
	mmio_req_o,
	mmio_addr_o,
	mmio_wdata_o,
	mmio_strb_o,
	mmio_we_o,
	mmio_rdata_i,
	mem_req_o,
	mem_addr_o,
	mem_wdata_o,
	mem_strb_o,
	mem_we_o,
	mem_rdata_o
);
	parameter [31:0] NumWords = 1048576;
	parameter [31:0] MMIOAddrWidth = 31;
	parameter [31:0] AddrWidth = 32;
	parameter [31:0] DataWidth = 64;
	parameter [31:0] StrbWidth = DataWidth >> 3;
	input clk_i;
	input rst_ni;
	output mmio_req_o;
	output [MMIOAddrWidth - 1:0] mmio_addr_o;
	output [DataWidth - 1:0] mmio_wdata_o;
	output [StrbWidth - 1:0] mmio_strb_o;
	output mmio_we_o;
	input [DataWidth - 1:0] mmio_rdata_i;
	output mem_req_o;
	output [AddrWidth - 1:0] mem_addr_o;
	output [DataWidth - 1:0] mem_wdata_o;
	output [StrbWidth - 1:0] mem_strb_o;
	output mem_we_o;
	output [DataWidth - 1:0] mem_rdata_o;
	boom_mem_top i_mem_top(
		.clock(clk_i),
		.reset_wire_reset(~rst_ni),
		.mmio_req_o(mmio_req_o),
		.mmio_we_o(mmio_we_o),
		.mmio_addr_o(mmio_addr_o),
		.mmio_strb_o(mmio_strb_o),
		.mmio_data_o(mmio_wdata_o),
		.mmio_data_i(mmio_rdata_i),
		.mem_req_o(mem_req_o),
		.mem_we_o(mem_we_o),
		.mem_addr_o(mem_addr_o),
		.mem_strb_o(mem_strb_o),
		.mem_data_o(mem_wdata_o),
		.mem_data_i(mem_rdata_o)
	);
	// sram_mem #(
	// 	.Width(DataWidth),
	// 	.Depth(NumWords),
	// 	.RelocateRequestUp(64'h0000000010000000)
	// ) i_sram(
	// 	.clk_i(clk_i),
	// 	.rst_ni(rst_ni),
	// 	.req_i(mem_req_o),
	// 	.write_i(mem_we_o),
	// 	.addr_i(mem_addr_o >> 3),
	// 	.wdata_i(mem_wdata_o),
	// 	.wmask_i({{8 {mem_strb_o[7]}}, {8 {mem_strb_o[6]}}, {8 {mem_strb_o[5]}}, {8 {mem_strb_o[4]}}, {8 {mem_strb_o[3]}}, {8 {mem_strb_o[2]}}, {8 {mem_strb_o[1]}}, {8 {mem_strb_o[0]}}}),
	// 	.rdata_o(mem_rdata_o)
	// );
endmodule

module ClockDividerN (
	clk_out,
	clk_in
);
	parameter DIV = 1;
	output reg clk_out = 1'b0;
	input clk_in;
	localparam CWIDTH = $clog2(DIV);
	localparam LOW_CYCLES = DIV / 2;
	localparam HIGH_TRANSITION = LOW_CYCLES - 1;
	localparam LOW_TRANSITION = DIV - 1;
	generate
		if (DIV == 1) begin : genblk1
			always @(clk_in) clk_out = clk_in;
		end
		else begin : genblk1
			reg [CWIDTH - 1:0] count = HIGH_TRANSITION[CWIDTH - 1:0];
			always @(posedge clk_in)
				if (count == LOW_TRANSITION[CWIDTH - 1:0]) begin
					clk_out = 1'b0;
					count <= 1'sb0;
				end
				else begin
					if (count == HIGH_TRANSITION[CWIDTH - 1:0])
						clk_out = 1'b1;
					count <= count + 1'b1;
				end
		end
	endgenerate
endmodule
module EICG_wrapper (
	out,
	en,
	test_en,
	in
);
	output out;
	input en;
	input test_en;
	input in;
	reg en_latched;
	always @(*)
		if (!in)
			en_latched = en || test_en;
	assign out = en_latched && in;
endmodule
module GenericAnalogIOCell (
	pad,
	core
);
	inout pad;
	inout core;
	assign core = 1'bz;
	assign pad = core;
endmodule
module GenericDigitalGPIOCell (
	pad,
	i,
	ie,
	o,
	oe
);
	inout pad;
	output i;
	input ie;
	input o;
	input oe;
	assign pad = (oe ? o : 1'bz);
	assign i = (ie ? pad : 1'b0);
endmodule
module GenericDigitalInIOCell (
	pad,
	i,
	ie
);
	input pad;
	output i;
	input ie;
	assign i = (ie ? pad : 1'b0);
endmodule
module GenericDigitalOutIOCell (
	pad,
	o,
	oe
);
	output pad;
	input o;
	input oe;
	assign pad = (oe ? o : 1'bz);
endmodule
