	I1_i,
	I2_i,
	O1_i,
	O2_i
);
	input CSB1_i;
	input CSB2_i;
	input OEB1_i;
	input OEB2_i;
	input CE1_i;
	input CE2_i;
	input WEB1_i;
	input WEB2_i;
	input [4:0] A1_i;
	input [4:0] A2_i;
	input [0:0] I1_i;
	input [0:0] I2_i;
	output reg [0:0] O1_i;
	output reg [0:0] O2_i;
	reg [0:0] memory [31:0];
	reg [0:0] data_out1;
	reg [0:0] data_out2;
	wire RE1;
	wire WE1;
	wire RE2;
	wire WE2;
	and u1 (RE1, ~CSB1_i, WEB1_i);
	and u2 (WE1, ~CSB1_i, ~WEB1_i);
	and u3 (RE2, ~CSB2_i, WEB2_i);
	and u4 (WE2, ~CSB2_i, ~WEB2_i);
